# region: digest
def digest(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: intake
def intake(xs, factor=3):
    return [v * factor for v in xs]

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs[1:]]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(shape(render(intake(sift(digest(raw))))))

